const selectDueAccessRequests = `-- name: SelectDueAccessRequests :many
SELECT id, org_id, project_id, environment_id, policy_id, requester_principal_id, state
FROM access_requests
WHERE (state = 'open' AND review_expires_at <= $1)
   OR (state = 'granted' AND expires_at <= $1)
ORDER BY id
LIMIT 100
`

type SelectDueAccessRequestsRow struct {
	ID                   string
	OrgID                string
	ProjectID            string
	EnvironmentID        string
	PolicyID             string
	RequesterPrincipalID string
	State                string
}

// SelectDueAccessRequests is one bounded installation-wide sweep batch: open
// requests whose review window lapsed and granted requests whose absolute
// expiry passed. Expiry is already enforced by the chokepoint's row filter;
// the sweep is bookkeeping, session rotation and the audit event.
// hikyo:instance-scoped
func (q *Queries) SelectDueAccessRequests(ctx context.Context, now pgtype.Timestamptz) ([]SelectDueAccessRequestsRow, error) {
	rows, err := q.db.Query(ctx, selectDueAccessRequests, now)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []SelectDueAccessRequestsRow
	for rows.Next() {
		var i SelectDueAccessRequestsRow
		if err := rows.Scan(
			&i.ID,
			&i.OrgID,
			&i.ProjectID,
			&i.EnvironmentID,
			&i.PolicyID,
			&i.RequesterPrincipalID,
			&i.State,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const updateAccessPolicy = `-- name: UpdateAccessPolicy :execrows
UPDATE access_policies
SET capabilities = $1, max_duration_seconds = $2, min_approvals = $3,
    allow_self_approval = $4, request_ttl_seconds = $5, enabled = $6,
    version = version + 1, updated_at = $7
WHERE org_id = $8 AND project_id = $9 AND id = $10
`

type UpdateAccessPolicyParams struct {
	Capabilities       string
	MaxDurationSeconds int32
	MinApprovals       int32
	AllowSelfApproval  bool
	RequestTtlSeconds  int32
	Enabled            bool
	UpdatedAt          pgtype.Timestamptz
	OrgID              string
	ProjectID          string
	ID                 string
}

// UpdateAccessPolicy bumps version so every open request pinned to the older
// version fails closed at its next decision.
func (q *Queries) UpdateAccessPolicy(ctx context.Context, arg UpdateAccessPolicyParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateAccessPolicy,
		arg.Capabilities,
		arg.MaxDurationSeconds,
		arg.MinApprovals,
		arg.AllowSelfApproval,
		arg.RequestTtlSeconds,
		arg.Enabled,
		arg.UpdatedAt,
		arg.OrgID,
		arg.ProjectID,
		arg.ID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
